var n=`0685-poulet-yassa-guinean-style`;var t=`world-0685`;var s=`GN`;var a=`western-africa`;var o=4;var r=142;var l={en:`Poulet Yassa Guinean Style`,ua:`Курка яса по-гвінейськи`};var u={en:`Poulet Yassa Guinean Style is a Guinea classic prepared with chicken thigh, yellow onion, lemon juice, dijon mustard. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Курка яса по-гвінейськи, страва кухні країни Гвінея зі складниками: куряче стегно, жовта цибуля, лимонний сік, діжонська гірчиця. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var g=[{en:`Combine the seasoning ingredients and coat the main protein or vegetables. Rest covered in the refrigerator for about 90 minutes.`,ua:`Змішайте приправи й ретельно покрийте ними м’ясо або овочі. Маринуйте під накриттям у холодильнику приблизно 90 хвилин.`,t:[`marinating`],m:90,i:[[`chicken-thigh`,820,`g`],[`yellow-onion`,380,`g`],[`lemon-juice`,100,`ml`],[`dijon-mustard`,25,`g`],[`garlic`,4,`clove`]]},{en:`Grill over medium-high heat for about 18 minutes, turning regularly until charred outside and safely cooked inside.`,ua:`Смажте на грилі на середньо-сильному жарі приблизно 18 хвилин, регулярно перевертаючи до рум’яної скоринки та повної готовності всередині.`,t:[`grilling`],m:18,i:[[`sunflower-oil`,35,`ml`]]},{en:`Add the braising liquid and seasonings, cover and cook gently for about 30 minutes until the meat is tender and safely cooked.`,ua:`Додайте рідину та приправи для тушкування, накрийте кришкою й готуйте на малому вогні приблизно 30 хвилин до м’якості та повної готовності м’яса.`,t:[`braising`],m:30,i:[[`water`,350,`ml`],[`scotch-bonnet-pepper`,1,`pcs`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:4,i:[[`parsley`,20,`g`]]}];var d={slug:n,id:t,country:`GN`,region:a,servings:4,minutes:142,title:l,text:u,steps:g};export{s as country,d as default,t as id,r as minutes,a as region,o as servings,n as slug,g as steps,u as text,l as title};